/** UUID relations must accept IDs generated by the real first-run installation. */
export async function assertUuidRuntimeSchema(pool: {
  query: (sql: string) => Promise<{ rows: Array<Record<string, unknown>> }>
}) {
  const expected = [
    'consent_events.actor_id',
    'email_messages.email_template_id',
    'email_messages.parent_message_id',
    'email_templates.id',
    'email_templates.site_id',
    'audience_experiments.id',
    'audience_experiments.site_id',
    'network_settings.id',
  ]
  const result = await pool.query(`SELECT table_name, column_name, data_type
    FROM information_schema.columns WHERE table_schema='public'
    AND table_name IN ('consent_events','email_messages','email_templates','audience_experiments','network_settings')`)
  for (const path of expected) {
    const row = result.rows.find((r) => `${r.table_name}.${r.column_name}` === path)
    if (row?.data_type !== 'uuid')
      throw new Error(`Runtime UUID schema mismatch: ${path} is ${row?.data_type ?? 'missing'}.`)
  }
}
